import nucleux from "@nucleux/tokens/preset";

/** @type {import('tailwindcss').Config} */
export default {
  presets: [nucleux],
  content: [
    "./index.html",
    "./src/**/*.{js,ts,jsx,tsx}",
    // Required: Nucleux components ship Tailwind classes that your build must generate.
    "./node_modules/@nucleux/*/dist/**/*.{js,cjs}",
  ],
};

props.source:
export interface AccordionProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  /** Allow multiple panels open at once. */
  type?: "single" | "multiple";
  /** Initial open value(s). */
  defaultValue?: string | string[];
}

export interface AccordionItemProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Unique key identifying the panel controlled by this item. */
  value: string;
}

export interface AccordionTriggerProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Additional classes merged onto the full-width trigger row. */
  className?: string;
}

export interface AccordionContentProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Additional classes merged onto the collapsible panel body. */
  className?: string;
}

export interface AlertProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  /** Visual style: "info" (neutral, default), "success", "warning", or "destructive". */
  variant?: AlertVariant;
  /**
   * Alias of `variant` (MUI Alert vocabulary). Deprecated — use `variant`.
   * @deprecated Use `variant` instead. Alias kept so MUI-trained agents and
   *   users are caught; it maps 1:1 ("error" -> "destructive").
   */
  severity?: AlertVariant | "error";
  /** Optional bold title above the body. */
  title?: React.ReactNode;
  /** Custom icon; defaults to a variant-appropriate one. */
  icon?: React.ReactNode;
  /** Hide the leading icon entirely. */
  hideIcon?: boolean;
}

export interface AlertDialogProps {
  /** Whether the alert dialog is open. */
  open: boolean;
  /** Called when the dialog requests to close (Escape / a button). */
  onOpenChange: (open: boolean) => void;
  title: React.ReactNode;
  description?: React.ReactNode;
  /** Confirm button label. */
  confirmLabel?: string;
  /** Cancel button label. */
  cancelLabel?: string;
  onConfirm?: () => void;
  onCancel?: () => void;
  /** Style the confirm action as destructive. */
  destructive?: boolean;
  /** Extra content between the description and the actions. */
  children?: React.ReactNode;
  className?: string;
}

export interface AspectRatioProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Width / height ratio (e.g. 16/9). Defaults to 1 (square). */
  ratio?: number;
}

export interface AttachmentProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  /** File or attachment name. */
  name: React.ReactNode;
  /** Metadata line, e.g. `"PDF · 240 KB"`. */
  meta?: React.ReactNode;
  /** Image URL — renders a thumbnail tile instead of a document chip. */
  thumbnail?: string;
  /** Doctype icon for the document chip. Defaults to a document glyph. */
  icon?: React.ReactNode;
  /** Called when the remove control is used. Hidden if omitted. */
  onRemove?: () => void;
}

export interface AttachmentGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Additional classes merged onto the tray. */
  className?: string;
}

export interface AvatarProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Role used to pick a default icon and styling when no image/initials given. */
  role?: MessageRole;
  /** Optional image URL; takes precedence over initials and the role icon. */
  src?: string;
  /** Explicit initials. If omitted, derived from `name`. */
  initials?: string;
  /** Display name — used to derive initials and the default aria-label. */
  name?: string;
  /** Corner style. `rounded` suits entity/person avatars, `circle` suits chat. */
  shape?: "circle" | "rounded";
  /** Accessible label / alt text. */
  alt?: string;
}

export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** Visual style. */
  variant?: BadgeVariant;
  /** Optional icon rendered before the label. */
  icon?: React.ReactNode;
}

/** Breadcrumb navigation landmark. Compose with the parts below. */
export interface BreadcrumbProps extends React.HTMLAttributes<HTMLElement> {
  /** Additional classes merged onto the outer nav wrapper. */
  className?: string;
}

export interface BreadcrumbItemProps extends React.LiHTMLAttributes<HTMLLIElement> {
  /** Additional classes merged onto the crumb list item. */
  className?: string;
}

export interface BreadcrumbLinkProps extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  /** Additional classes merged onto the crumb anchor. */
  className?: string;
}

/** The current page — non-interactive, marked with aria-current. */
export interface BreadcrumbPageProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** Additional classes merged onto the current-page crumb. */
  className?: string;
}

export interface BreadcrumbSeparatorProps extends React.LiHTMLAttributes<HTMLLIElement> {
  /** Additional classes merged onto the separator glyph container. */
  className?: string;
  /** Custom separator glyph; defaults to a ChevronRight icon. */
  children?: React.ReactNode;
}

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Visual style: "primary" (default), "cta", "secondary", "ghost", "destructive", or "link". */
  variant?: ButtonVariant;
  /**
   * Alias of `variant` (MUI/Chakra vocabulary). Deprecated — use `variant`.
   * @deprecated Use `variant` instead. Alias kept so MUI/Chakra-trained
   *   agents and users are caught; it maps 1:1.
   */
  color?: ButtonVariant;
  /**
   * Size preset: "sm", "md" (default), "lg", or a square icon-only size
   * ("icon-sm", "icon", "icon-lg"). Icon-only buttons need an `aria-label`.
   */
  size?: ButtonSize;
  /**
   * Render the single child element (e.g. an `<a>` or a router `Link`) with
   * the button's styles instead of a `<button>`. `leftIcon`/`rightIcon` are
   * ignored; put icons inside the child.
   */
  asChild?: boolean;
  /** Icon rendered before the label. */
  leftIcon?: React.ReactNode;
  /** Icon rendered after the label. */
  rightIcon?: React.ReactNode;
}

/** Card header. Lays children out in a row with space-between by default. */
export interface CardHeaderProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Additional classes merged onto the card header row. */
  className?: string;
}

export interface CardTitleProps extends React.HTMLAttributes<HTMLHeadingElement> {
  /** Additional classes merged onto the card title. */
  className?: string;
}

export interface CardDescriptionProps extends React.HTMLAttributes<HTMLParagraphElement> {
  /** Additional classes merged onto the card description. */
  className?: string;
}

/** Trailing action in a card header, e.g. a "View all" link. Renders a button by default. */
export interface CardActionProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Additional classes merged onto the header action button. */
  className?: string;
  /** Button type. Defaults to "button". */
  type?: "button" | "submit" | "reset";
}

export interface CardContentProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Additional classes merged onto the card body. */
  className?: string;
}

/** Full-bleed hairline divider between card sections. */
export interface CardDividerProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Additional classes merged onto the divider. */
  className?: string;
}

export interface CarouselProps extends React.HTMLAttributes<HTMLDivElement> {
  orientation?: Orientation;
  opts?: EmblaOptionsType;
  /** Receive the Embla API instance once ready. */
  setApi?: (api: EmblaCarouselType | undefined) => void;
}

export interface CaveatProps extends React.HTMLAttributes<HTMLParagraphElement> {
  /** Leading icon. Defaults to an info glyph. Pass `null` to omit. */
  icon?: React.ReactNode;
}

export interface ChartContainerProps extends React.HTMLAttributes<HTMLDivElement> {
  config: ChartConfig;
  /** A single recharts chart element (BarChart, LineChart, …). */
  children: React.ReactElement;
}

export interface ChartTooltipContentProps {
  active?: boolean;
  payload?: TooltipPayloadItem[];
  label?: React.ReactNode;
  config?: ChartConfig;
}

export interface ChartLegendContentProps {
  payload?: LegendPayloadItem[];
  config?: ChartConfig;
}

export interface CheckboxProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onChange" | "value" | "type"> {
  /** Controlled checked state. */
  checked?: boolean;
  /** Initial state when uncontrolled. */
  defaultChecked?: boolean;
  /** Called with the next checked state. */
  onCheckedChange?: (checked: boolean) => void;
}

export interface CodeBlockProps extends React.HTMLAttributes<HTMLDivElement> {
  /** The raw source code to display. */
  code: string;
  /** Language label shown in the header (e.g. "ts", "python"). */
  language?: string;
  /** Hide the copy button. */
  hideCopy?: boolean;
}

export interface CollapsibleProps extends React.HTMLAttributes<HTMLDivElement> {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  disabled?: boolean;
}

export interface CollapsibleTriggerProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Hide the default chevron affordance. */
  hideChevron?: boolean;
}

export interface ComboboxProps {
  options: ComboboxOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  placeholder?: string;
  searchPlaceholder?: string;
  emptyText?: string;
  disabled?: boolean;
  className?: string;
  /** Accessible name for the trigger. */
  "aria-label"?: string;
}

export interface CommandGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  heading?: React.ReactNode;
}

export interface CommandItemProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSelect"> {
  /** The value used for filtering + selection. Defaults to the text content. */
  value: string;
  disabled?: boolean;
  onSelect?: (value: string) => void;
}

export interface ConnectorProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  /** Connector name, e.g. `"GitHub"`. */
  name: React.ReactNode;
  /** What the connector gives the agent access to. */
  description?: React.ReactNode;
  /** Connector logo/icon. Defaults to a plug glyph. */
  icon?: React.ReactNode;
  /** Whether the connector is already connected. */
  connected?: boolean;
  /** Called to connect. Renders the connect button when set and not connected. */
  onConnect?: () => void;
  /** Called to disconnect. Renders a manage/disconnect control when connected. */
  onDisconnect?: () => void;
  /** Label for the connect action. Defaults to a localized "Connect". */
  connectLabel?: React.ReactNode;
  /** Label for the disconnect action. Defaults to a localized "Disconnect". */
  disconnectLabel?: React.ReactNode;
}

export interface ConsentProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  /** Heading of the consent card. */
  title: React.ReactNode;
  description?: React.ReactNode;
  /** The permissions the user can grant. */
  permissions: ConsentPermission[];
  /** Label for the deny button. */
  denyLabel?: string;
  /** Called when the user denies all permissions. */
  onDeny?: () => void;
  /** Optional middle action, e.g. "Always Allow". */
  secondaryLabel?: string;
  /** Called with the selected permission ids when the secondary action runs. */
  onSecondary?: (selectedIds: string[]) => void;
  /** Label for the allow button. */
  allowLabel?: string;
  /** Called with the ids of the granted permissions. */
  onAllow?: (selectedIds: string[]) => void;
}

export interface ContextMenuProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "content"> {
  /** Menu items — compose ContextMenuItem / ContextMenuSeparator / ContextMenuLabel. */
  content: React.ReactNode;
  /** The area that opens the menu on right-click. */
  children: React.ReactNode;
}

export interface ContextMenuItemProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  icon?: React.ReactNode;
  trailing?: React.ReactNode;
  destructive?: boolean;
}

export interface DataTableProps<TData, TValue> {
  columns: ColumnDef<TData, TValue>[];
  data: TData[];
  /** Rows per page. Set 0 to disable pagination. */
  pageSize?: number;
  /** Message shown when there are no rows. */
  emptyMessage?: React.ReactNode;
  className?: string;
}

export interface DatePickerProps {
  value?: Date;
  defaultValue?: Date;
  onValueChange?: (date: Date | undefined) => void;
  placeholder?: string;
  disabled?: boolean;
  /** Disable individual days. */
  isDateDisabled?: (date: Date) => boolean;
  /** Classes for the root; sets the width (default `w-60`; pass `w-full` in forms). */
  className?: string;
  "aria-label"?: string;
}

export interface DialogProps {
  /** Whether the dialog is open. */
  open: boolean;
  /** Called when the dialog requests to close (overlay click / Escape). */
  onOpenChange: (open: boolean) => void;
  /** Panel content — compose DialogHeader/Title/Description/Footer. */
  children: React.ReactNode;
  /** Class overrides for the panel. */
  className?: string;
  /** Disable closing on overlay click / Escape. */
  dismissible?: boolean;
}

export interface DialogHeaderProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Additional classes merged onto the header slot. */
  className?: string;
}

export interface DialogTitleProps extends React.HTMLAttributes<HTMLHeadingElement> {
  /** Additional classes merged onto the title. */
  className?: string;
}

export interface DialogDescriptionProps extends React.HTMLAttributes<HTMLParagraphElement> {
  /** Additional classes merged onto the description. */
  className?: string;
}

export interface DialogFooterProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Additional classes merged onto the footer slot. */
  className?: string;
}

export interface DisclosureProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Presentation: inline `pill`, corner `badge`, or full-width `banner`. */
  variant?: DisclosureVariant;
  /** Leading icon. Defaults to a sparkle. */
  icon?: React.ReactNode;
  /** Label / message. Ignored if `children` is provided. Has a per-variant default. */
  label?: React.ReactNode;
}

export interface DropdownMenuProps {
  /** Whether the menu is open (controlled). */
  open?: boolean;
  /** Initial open state (uncontrolled). */
  defaultOpen?: boolean;
  /** Called when the menu opens or closes. */
  onOpenChange?: (open: boolean) => void;
  children: React.ReactNode;
}

export interface DropdownMenuTriggerProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Render the single child (e.g. a `<Button>`) as the trigger instead of a plain `<button>`. */
  asChild?: boolean;
}

export interface DropdownMenuContentProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Horizontal alignment relative to the trigger. */
  align?: "start" | "end";
  /** Open below (default) or above the trigger. */
  side?: "bottom" | "top";
}

export interface DropdownMenuItemProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onSelect"> {
  /** "destructive" styles a delete-style action. */
  variant?: "default" | "destructive";
  /** Indent to line up with items that have an icon. */
  inset?: boolean;
  /** Called when the item is chosen (click, Enter or Space). Call `event.preventDefault()` to keep the menu open. */
  onSelect?: (event: Event) => void;
}

export interface DropdownMenuLabelProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Indent to line up with items that have an icon. */
  inset?: boolean;
}

export interface EmptyMediaProps extends React.HTMLAttributes<HTMLDivElement> {
  /** "icon" puts the child icon in a muted rounded tile; "default" renders it as-is (e.g. an avatar or illustration). */
  variant?: "default" | "icon";
}

export interface GlobalNavProps extends React.HTMLAttributes<HTMLElement> {
  /** Leading content — brand mark, page heading, breadcrumbs. */
  left?: React.ReactNode;
  /** Centered content — typically a search field. */
  center?: React.ReactNode;
  /** Trailing content — notifications, account avatar, actions. */
  right?: React.ReactNode;
}

export interface HoverCardProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "content"> {
  /** The element that reveals the card on hover/focus. */
  trigger: React.ReactNode;
  /** The floating card content. */
  content: React.ReactNode;
  side?: "top" | "bottom";
  align?: "start" | "center" | "end";
  /** Delay in ms before opening on hover. */
  openDelay?: number;
  /** Delay in ms before closing after leaving. */
  closeDelay?: number;
}

export interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  /** Render an error ring and set `aria-invalid`. */
  invalid?: boolean;
}

export interface InputOtpProps {
  /** Number of code cells. */
  length?: number;
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  /** Fired once every cell is filled. */
  onComplete?: (value: string) => void;
  disabled?: boolean;
  /** Only accept digits (default true). */
  numeric?: boolean;
  className?: string;
  "aria-label"?: string;
}

export interface KnowledgeBaseProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  /** The available knowledge sources. */
  sources: KnowledgeSource[];
  /** Selected source ids (controlled). */
  value?: string[];
  /** Initial selection (uncontrolled). */
  defaultValue?: string[];
  /** Called when the selection changes. */
  onValueChange?: (ids: string[]) => void;
  /** Heading above the list. Defaults to `"Knowledge sources"`. */
  heading?: React.ReactNode;
}

export interface LabelProps extends React.LabelHTMLAttributes<HTMLLabelElement> {
  /** Show a destructive-colored asterisk to mark the field required. */
  required?: boolean;
}

export interface Md3ActionConfirmationProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  title: React.ReactNode;
  description?: React.ReactNode;
  variant?: Md3ActionConfirmationVariant;
  badge?: React.ReactNode;
  icon?: React.ReactNode;
  confirmLabel?: React.ReactNode;
  cancelLabel?: React.ReactNode;
  onConfirm?: () => void;
  onCancel?: () => void;
}

export interface Md3AgentComposerProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSubmit"> {
  value: string;
  onValueChange: (value: string) => void;
  onSubmit: (value: string) => void;
  placeholder?: string;
  leftActions?: React.ReactNode;
  rightActions?: React.ReactNode;
  loading?: boolean;
  onStop?: () => void;
  maxHeight?: number;
  disabled?: boolean;
}

export interface Md3BadgeProps extends Omit<React.HTMLAttributes<HTMLSpanElement>, "content"> {
  /** Numeric/text count. Omit for a small dot badge. */
  content?: React.ReactNode;
  /** Clamp numeric content, e.g. max=99 renders "99+". */
  max?: number;
  /** The element the badge is attached to (badge floats at its top-right). */
  children?: React.ReactNode;
}

export interface Md3BannerProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Leading icon. */
  icon?: React.ReactNode;
  /** Trailing action buttons (typically text buttons). */
  actions?: React.ReactNode;
}

export interface Md3BottomSheetProps extends React.HTMLAttributes<HTMLDivElement> {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** Show the drag handle at the top (default true). */
  showHandle?: boolean;
  dismissible?: boolean;
}

export interface Md3ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: Md3ButtonVariant;
  /** Leading icon element. */
  icon?: React.ReactNode;
}

export interface Md3CardProps extends React.HTMLAttributes<HTMLDivElement> {
  variant?: Md3CardVariant;
  /** Add hover/press state layer + pointer cursor (for actionable cards). */
  interactive?: boolean;
}

export interface Md3CheckboxProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onChange" | "type"> {
  checked?: boolean;
  defaultChecked?: boolean;
  indeterminate?: boolean;
  onCheckedChange?: (checked: boolean) => void;
}

export interface Md3ChipProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onSelect"> {
  variant?: Md3ChipVariant;
  /** Filter chips: selected state (shows a leading check). */
  selected?: boolean;
  /** Leading icon (assist/input/suggestion). */
  icon?: React.ReactNode;
  /** Input chips: renders a trailing remove button and fires this on click. */
  onRemove?: () => void;
}

export interface Md3DatePickerProps {
  value?: Date;
  defaultValue?: Date;
  onValueChange?: (date: Date | undefined) => void;
  label?: string;
  disabled?: boolean;
  className?: string;
  "aria-label"?: string;
}

export interface Md3DialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  headline: React.ReactNode;
  /** Optional hero icon, centered above the headline. */
  icon?: React.ReactNode;
  /** Supporting body content. */
  children?: React.ReactNode;
  /** Action buttons (typically text buttons), right-aligned. */
  actions?: React.ReactNode;
  /** Close on scrim click / Escape (default true). */
  dismissible?: boolean;
  className?: string;
}

export interface Md3DividerProps extends React.HTMLAttributes<HTMLDivElement> {
  orientation?: "horizontal" | "vertical";
  /** Inset the divider (e.g. to align with list text). */
  inset?: boolean;
}

export interface Md3FabProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  size?: Md3FabSize;
  color?: Md3FabColor;
  icon: React.ReactNode;
}

export interface Md3IconButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: Md3IconButtonVariant;
  /** Toggle-selected state (affects filled/tonal background). */
  selected?: boolean;
  /** Required for icon-only buttons. */
  "aria-label": string;
}

export interface Md3ListItemProps extends React.HTMLAttributes<HTMLDivElement> {
  headline: React.ReactNode;
  supportingText?: React.ReactNode;
  leading?: React.ReactNode;
  trailing?: React.ReactNode;
  /** Add a hover/press state layer + role="button" for actionable rows. */
  interactive?: boolean;
}

export interface Md3MenuItemProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  icon?: React.ReactNode;
  /** Trailing content — a shortcut hint or submenu marker. */
  trailing?: React.ReactNode;
}

export interface Md3MessageProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Who authored the message. */
  role: MessageRole;
  /** Message text. Ignored if `children` is provided. */
  content?: string;
  /** True while the assistant is still streaming this message. */
  streaming?: boolean;
  /** Hide the avatar (e.g. for consecutive same-role messages). */
  hideAvatar?: boolean;
  /** Custom node rendered in place of the default avatar. */
  avatar?: React.ReactNode;
}

export interface Md3NavigationBarProps
  extends Omit<React.HTMLAttributes<HTMLElement>, "defaultValue"> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
}

export interface Md3NavigationBarItemProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  value: string;
  icon: React.ReactNode;
  label: React.ReactNode;
}

export interface Md3NavigationDrawerProps
  extends Omit<React.HTMLAttributes<HTMLElement>, "defaultValue"> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Render as a modal drawer with a scrim (controlled via open/onOpenChange). */
  modal?: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
}

export interface Md3NavigationDrawerItemProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  value: string;
  icon?: React.ReactNode;
  /** Trailing content (e.g. a count). */
  trailing?: React.ReactNode;
}

export interface Md3NavigationRailProps
  extends Omit<React.HTMLAttributes<HTMLElement>, "defaultValue"> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Optional header content (e.g. a menu button or FAB), shown at the top. */
  header?: React.ReactNode;
}

export interface Md3NavigationRailItemProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  value: string;
  icon: React.ReactNode;
  label: React.ReactNode;
}

export interface Md3LinearProgressProps extends React.HTMLAttributes<HTMLDivElement> {
  /** 0–100. Omit for an indeterminate indicator. */
  value?: number;
  "aria-label"?: string;
}

export interface Md3CircularProgressProps extends React.HTMLAttributes<HTMLDivElement> {
  /** 0–100. Omit for an indeterminate spinner. */
  value?: number;
  /** Diameter in px. */
  size?: number;
  strokeWidth?: number;
  "aria-label"?: string;
}

export interface Md3RadioGroupProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Accessible label for the group. */
  label?: string;
}

export interface Md3RadioProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "value"> {
  value: string;
}

export interface Md3SearchProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "value" | "onChange"> {
  value?: string;
  onValueChange?: (value: string) => void;
  /** Leading element (defaults to a search icon). */
  leading?: React.ReactNode;
  /** Trailing element (e.g. an avatar or icon button). */
  trailing?: React.ReactNode;
}

export interface Md3SegmentedButtonProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> {
  type?: "single" | "multiple";
  value?: string | string[];
  defaultValue?: string | string[];
  onValueChange?: (value: string | string[]) => void;
}

export interface Md3SegmentedButtonItemProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  value: string;
  icon?: React.ReactNode;
}

export interface Md3SliderProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "defaultValue" | "onChange"> {
  value?: number;
  defaultValue?: number;
  min?: number;
  max?: number;
  step?: number;
  disabled?: boolean;
  onValueChange?: (value: number) => void;
  "aria-label"?: string;
}

export interface Md3SnackbarProps extends React.HTMLAttributes<HTMLDivElement> {
  open: boolean;
  message: React.ReactNode;
