export interface NativeSelectProps extends React.SelectHTMLAttributes<HTMLSelectElement> {
  /** Wrapper className (the chevron is positioned within it). */
  containerClassName?: string;
}

/**
 * An expanded vertical navigation panel (docs/library sidebar) with a header,
 * collapsible {@link NavSection}s, and text {@link NavItem}s.
 */
export interface NavPanelProps extends React.HTMLAttributes<HTMLElement> {
  /** Additional classes merged onto the nav column. */
  className?: string;
}

export interface NavPanelHeaderProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Trailing meta text, e.g. a count. */
  meta?: React.ReactNode;
}

export interface NavSectionProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  /** Section title. */
  title: React.ReactNode;
  /** Whether the section is collapsible (shows a chevron toggle). */
  collapsible?: boolean;
  /** Initial open state (collapsible sections). */
  defaultOpen?: boolean;
}

export interface NavItemProps extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  /** Marks the item as the current page. */
  active?: boolean;
}

export interface NavigationMenuItemProps extends React.LiHTMLAttributes<HTMLLIElement> {
  value?: string;
}

export interface NavigationMenuLinkProps extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  active?: boolean;
}

export interface OpenInputProps
  extends Omit<React.TextareaHTMLAttributes<HTMLTextAreaElement>, "onSubmit" | "value" | "onChange"> {
  /** Controlled value of the input. */
  value: string;
  /** Called when the value changes. */
  onValueChange: (value: string) => void;
  /** Called with the trimmed value on submit (Enter or button). */
  onSubmit: (value: string) => void;
  /** Show the agent as busy — swaps the send button for a stop button. */
  loading?: boolean;
  /** Called when the stop button is pressed while `loading`. */
  onStop?: () => void;
  /** Max auto-grow height in px before scrolling. */
  maxHeight?: number;
}

export interface PaginationProps extends Omit<React.HTMLAttributes<HTMLElement>, "onChange"> {
  /** 1-based current page. */
  page: number;
  /** Total number of pages. */
  count: number;
  onPageChange: (page: number) => void;
  /** How many page buttons to show around the current page. */
  siblingCount?: number;
}

export interface PersonalityProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  /** Tone options. Defaults to {@link defaultTones}. */
  options?: ToneOption[];
  /** Selected value (controlled). */
  value?: string;
  /** Initial value (uncontrolled). */
  defaultValue?: string;
  /** Called when a tone is chosen. */
  onValueChange?: (value: string) => void;
  /** Group label. Defaults to `"Tone"`. */
  label?: React.ReactNode;
}

export interface PopoverProps {
  /** Whether the popover is open (controlled). */
  open?: boolean;
  /** Initial open state (uncontrolled). */
  defaultOpen?: boolean;
  /** Called when the popover requests to open or close. */
  onOpenChange?: (open: boolean) => void;
  children: React.ReactNode;
}

export interface PopoverTriggerProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Additional classes merged onto the trigger button. */
  className?: string;
  /** Button type. Defaults to "button". */
  type?: "button" | "submit" | "reset";
}

export interface PopoverContentProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Horizontal alignment relative to the trigger. */
  align?: "start" | "end";
  /**
   * Alias of `align` (CSS flex vocabulary). Deprecated — use `align`.
   * @deprecated Use `align` instead. Alias kept so agents reaching for the
   *   CSS property name are caught; it maps 1:1.
   */
  alignItems?: "start" | "end";
}

export interface ProgressProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Current value (0–max). Omit for an indeterminate bar. */
  value?: number;
  /** Maximum value. */
  max?: number;
  /** Thickness preset: "sm" or "md" (default). */
  size?: ProgressSize;
  /** Class applied to the filled indicator (e.g. "bg-success"). */
  indicatorClassName?: string;
}

export interface RadioGroupProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  /** Controlled selected value. */
  value?: string;
  /** Initial value when uncontrolled. */
  defaultValue?: string;
  /** Called with the newly selected value. */
  onValueChange?: (value: string) => void;
  /** Accessible group label. */
  label?: string;
}

export interface RadioProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "value" | "type"> {
  /** The value this radio represents. */
  value: string;
}

export interface ResizablePanelGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  direction?: Direction;
}

export interface ResizablePanelProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Initial size as a flex-grow weight (defaults to 1). */
  defaultSize?: number;
}

export interface ResizableHandleProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Show the grip dots affordance. */
  withHandle?: boolean;
  /** Accessible name for the splitter. */
  "aria-label"?: string;
}

export interface ScrollAreaProps extends React.HTMLAttributes<HTMLDivElement> {
  orientation?: "vertical" | "horizontal" | "both";
  /** Max height (any CSS length) for the vertical scroll viewport. */
  viewportClassName?: string;
}

export interface SeparatorProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Axis of the rule: "horizontal" (default) or "vertical". */
  orientation?: "horizontal" | "vertical";
  /** Purely visual (no semantic meaning for assistive tech). Defaults to true. */
  decorative?: boolean;
}

export interface SheetProps {
  /** Whether the sheet is open. */
  open: boolean;
  /** Called when the sheet requests to close (overlay click / Escape / close button). */
  onOpenChange: (open: boolean) => void;
  /** Which edge the sheet slides in from. */
  side?: SheetSide;
  /** Panel content — compose SheetHeader/Title/Description/Body/Footer. */
  children: React.ReactNode;
  /** Class overrides for the panel. */
  className?: string;
  /** Disable closing on overlay click / Escape. */
  dismissible?: boolean;
}

export interface SheetHeaderProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Additional classes merged onto the sheet header. */
  className?: string;
}

export interface SheetTitleProps extends React.HTMLAttributes<HTMLHeadingElement> {
  /** Additional classes merged onto the title. */
  className?: string;
}

export interface SheetDescriptionProps extends React.HTMLAttributes<HTMLParagraphElement> {
  /** Additional classes merged onto the description. */
  className?: string;
}

export interface SheetBodyProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Additional classes merged onto the sheet body. */
  className?: string;
}

export interface SheetFooterProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Additional classes merged onto the sheet footer. */
  className?: string;
}

/** A button that closes the enclosing Sheet. */
export interface SheetCloseProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Additional classes merged onto the close button. */
  className?: string;
  /** Button type. Defaults to "button". */
  type?: "button" | "submit" | "reset";
}

/**
 * Collapsed application sidebar — a narrow vertical icon rail. Compose a brand
 * mark, {@link SidebarItem}s, {@link SidebarSeparator}s, and a pinned `footer`:
 *
 * ```tsx
 * <Sidebar footer={<SidebarItem icon={<Settings />} label="Settings" />}>
 *   <BrandMark />
 *   <SidebarItem icon={<Home />} label="Home" active />
 *   <SidebarItem icon={<Sparkles />} label="Assistant" />
 * </Sidebar>
 * ```
 */
export interface SidebarProps extends React.HTMLAttributes<HTMLElement> {
  /** Content pinned to the bottom of the rail (e.g. settings). */
  footer?: React.ReactNode;
}

export interface SidebarItemProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** The icon to render. */
  icon: React.ReactNode;
  /** Accessible label + tooltip (rail is icon-only). */
  label: string;
  /** Marks the item as the current page. */
  active?: boolean;
}

/** Horizontal hairline separating groups of sidebar items. */
export interface SidebarSeparatorProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Additional classes merged onto the separator. */
  className?: string;
}

export interface SkeletonProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Pill shape for text/avatar placeholders. */
  circle?: boolean;
}

export interface SliderProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "defaultValue" | "onChange"> {
  value?: number;
  defaultValue?: number;
  min?: number;
  max?: number;
  step?: number;
  disabled?: boolean;
  onValueChange?: (value: number) => void;
  /** Accessible name for the thumb (falls back to aria-label on the root). */
  "aria-label"?: string;
}

export interface StructuredInputProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange" | "onSubmit"> {
  /** The clarifying question the agent is asking. */
  question: React.ReactNode;
  /** The selectable answers. */
  options: StructuredOption[];
  /** Allow selecting more than one option. */
  multiple?: boolean;
  /** Selected values (controlled). */
  value?: string[];
  /** Initial selection (uncontrolled). */
  defaultValue?: string[];
  /** Called when the selection changes. */
  onValueChange?: (values: string[]) => void;
  /** Show a free-text "something else" escape. */
  allowOther?: boolean;
  /** Label for the other escape. Defaults to `"Something else…"`. */
  otherPlaceholder?: string;
  /** Called when the answer is submitted. */
  onSubmit?: (values: string[], other?: string) => void;
  /** Called when the user skips the question. Renders the skip control when set. */
  onSkip?: () => void;
  /** Label for the submit button. */
  submitLabel?: React.ReactNode;
  /** Label for the skip button. */
  skipLabel?: React.ReactNode;
}

/** A single suggestion pill — a secondary-styled action button. */
export interface SuggestedPromptProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Additional classes merged onto the chip. */
  className?: string;
  /** Button type. Defaults to "button". */
  type?: "button" | "submit" | "reset";
}

export interface SuggestedPromptsProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSelect"> {
  /** Convenience: render a chip per string and call `onSelect` on click. */
  items?: string[];
  /** Called with the selected suggestion text. */
  onSelect?: (value: string) => void;
}

export interface SwitchProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onChange" | "value"> {
  /** Controlled on/off state. */
  checked?: boolean;
  /** Initial state when uncontrolled. */
  defaultChecked?: boolean;
  /** Called with the next state when toggled. */
  onCheckedChange?: (checked: boolean) => void;
  /** Size preset: "sm" or "md" (default). */
  size?: SwitchSize;
}

/** Scroll-wrapped table root. */
export interface TableProps extends React.TableHTMLAttributes<HTMLTableElement> {
  /** Additional classes for the inner <table> element. */
  className?: string;
}

export interface TableHeaderProps extends React.HTMLAttributes<HTMLTableSectionElement> {
  /** Additional classes merged onto the <thead>. */
  className?: string;
}

export interface TableBodyProps extends React.HTMLAttributes<HTMLTableSectionElement> {
  /** Additional classes merged onto the <tbody>. */
  className?: string;
}

export interface TableRowProps extends React.HTMLAttributes<HTMLTableRowElement> {
  /** Additional classes merged onto the row. */
  className?: string;
}

export interface TableHeadProps extends React.ThHTMLAttributes<HTMLTableCellElement> {
  /** Additional classes merged onto the header cell. */
  className?: string;
}

export interface TableCellProps extends React.TdHTMLAttributes<HTMLTableCellElement> {
  /** Additional classes merged onto the data cell. */
  className?: string;
}

export interface TableCaptionProps extends React.HTMLAttributes<HTMLTableCaptionElement> {
  /** Additional classes merged onto the caption. */
  className?: string;
}

export interface TabsProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  /** Controlled active tab value. */
  value?: string;
  /** Initial active tab when uncontrolled. */
  defaultValue?: string;
  /** Called with the newly selected value. */
  onValueChange?: (value: string) => void;
  /** Layout axis of the tab list: "horizontal" (default) or "vertical". */
  orientation?: Orientation;
}

export interface TabsListProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Additional classes merged onto the tab strip. */
  className?: string;
  /** Extra keydown handler; runs before the built-in roving-focus handling. */
  onKeyDown?: React.KeyboardEventHandler<HTMLDivElement>;
}

export interface TabsTriggerProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Value linking this trigger to its TabsContent. */
  value: string;
}

export interface TabsContentProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Tab id this panel belongs to (matches a TabsTrigger value). */
  value: string;
}

export interface TemplatesProps
  extends Omit<React.FormHTMLAttributes<HTMLFormElement>, "onSubmit"> {
  /** The template as an ordered mix of literal text and named slots. */
  segments: PromptSegment[];
  /** Slot values (controlled), keyed by slot id. */
  values?: Record<string, string>;
  /** Initial slot values (uncontrolled). */
  defaultValues?: Record<string, string>;
  /** Called when any slot changes. */
  onValuesChange?: (values: Record<string, string>) => void;
  /** Called with the interpolated prompt (and raw values) on submit. */
  onComplete?: (prompt: string, values: Record<string, string>) => void;
  /** Submit button label. Defaults to `"Use this prompt"`. */
  submitLabel?: React.ReactNode;
}

export interface TextareaProps extends React.TextareaHTMLAttributes<HTMLTextAreaElement> {
  /** Render an error ring and set `aria-invalid`. */
  invalid?: boolean;
}

export interface ToastProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  /** Visual style: "info" (default), "success", "warning", or "destructive". */
  variant?: ToastVariant;
  /** Bold title line of the toast. */
  title?: React.ReactNode;
  /** Supporting body copy below the title. */
  description?: React.ReactNode;
  /** Renders a close button that calls this handler. */
  onClose?: () => void;
}

export interface ToastProviderProps {
  children: React.ReactNode;
  /** Viewport placement. */
  placement?: "top" | "bottom";
}

export interface ToggleProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onChange"> {
  /** Controlled pressed state. */
  pressed?: boolean;
  /** Uncontrolled initial pressed state. */
  defaultPressed?: boolean;
  /** Fired with the next pressed state on activation. */
  onPressedChange?: (pressed: boolean) => void;
  variant?: "default" | "outline";
  size?: "sm" | "md" | "lg";
}

export interface ToggleGroupProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> {
  /** "single" allows one active item; "multiple" allows many. */
  type?: "single" | "multiple";
  value?: Value | Value[];
  defaultValue?: Value | Value[];
  onValueChange?: (value: Value | Value[]) => void;
  size?: "sm" | "md" | "lg";
  variant?: "default" | "outline";
}

export interface ToggleGroupItemProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  value: Value;
}

export interface TooltipProps extends Omit<React.HTMLAttributes<HTMLSpanElement>, "content"> {
  /** The tooltip text/content. */
  content: React.ReactNode;
  /** Which side of the trigger to show on. */
  side?: TooltipSide;
  /** The trigger element(s). */
  children: React.ReactNode;
}

export interface VoiceInputProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Current state of the dictation flow. */
  state?: VoiceInputState;
  /** Elapsed time label while recording, e.g. `"0:12"`. */
  duration?: React.ReactNode;
  /** Transcribed text shown once available. */
  transcript?: React.ReactNode;
  /** Called from the idle mic button to start recording. */
  onStart?: () => void;
  /** Called to cancel/discard the recording. */
  onCancel?: () => void;
  /** Called to stop recording and confirm. */
  onConfirm?: () => void;
}

