import { useState } from "react";
import type { Meta, StoryObj } from "@storybook/react";
import { Bell, Calendar, Home, ListChecks, Settings, Sparkles } from "lucide-react";
import {
  Avatar,
  Button,
  Caveat,
  GlobalNav,
  Input,
  Message,
  MessageScroller,
  OpenInput,
  Sidebar,
  SidebarItem,
  SuggestedPrompts,
} from "../index";

/**
 * A full agent chat screen assembled from Nucleux primitives — app shell, a
 * message list with a streaming reply, suggested prompts, the open input, and
 * the fallibility caveat.
 */
const meta = {
  title: "Examples/Agent Chat",
  parameters: { layout: "fullscreen" },
} satisfies Meta;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  render: () => {
    const [value, setValue] = useState("");
    return (
      <div className="flex h-screen flex-col bg-background">
        <GlobalNav
          left={<span className="text-base font-medium text-foreground">Nebula</span>}
          center={<Input type="search" aria-label="Search" placeholder="Search" className="w-72" />}
          right={
            <>
              <Button variant="ghost" size="icon-lg" aria-label="Notifications">
                <Bell />
              </Button>
              <Avatar name="Eric" className="size-8" />
            </>
          }
        />

        <div className="flex min-h-0 flex-1">
          <Sidebar footer={<SidebarItem icon={<Settings />} label="Settings" />}>
            <SidebarItem icon={<Home />} label="Home" />
            <SidebarItem icon={<Sparkles />} label="Assistant" active />
            <SidebarItem icon={<Calendar />} label="Calendar" />
            <SidebarItem icon={<ListChecks />} label="Tasks" />
          </Sidebar>

          <main className="flex min-w-0 flex-1 flex-col">
            <MessageScroller className="mx-auto w-full max-w-3xl">
              <Message role="user" content="Summarize the CPQ Q3 scope review and list the action items." />
              <Message
                role="assistant"
                content="Here's the summary: the team aligned on a phased CPQ rollout, with pricing rules landing first. Three action items were captured."
              />
              <Message role="assistant" streaming content="Drafting the action item list" />
            </MessageScroller>

            <div className="mx-auto w-full max-w-3xl space-y-3 p-4">
              <SuggestedPrompts
                items={["List action items", "Draft a follow-up email", "Show decisions"]}
                onSelect={setValue}
              />
              <OpenInput value={value} onValueChange={setValue} onSubmit={() => setValue("")} />
              <Caveat />
            </div>
          </main>
        </div>
      </div>
    );
  },
};

import type { Meta, StoryObj } from "@storybook/react";
import { ArrowUpRight, Play, TrendingUp, Users } from "lucide-react";
import {
  Avatar,
  Badge,
  Button,
  CardAction,
  CardContainer,
  CardContent,
  CardDescription,
  CardDivider,
  CardHeader,
  CardTitle,
  Progress,
} from "../index";

/**
 * A gallery of card layouts ("card variations") — all built from the same
 * CardContainer primitive plus Badge, Avatar, Progress, and Button.
 */
const meta = {
  title: "Examples/Card Gallery",
  parameters: { layout: "padded" },
} satisfies Meta;

export default meta;
type Story = StoryObj<typeof meta>;

function StatCard() {
  return (
    <CardContainer>
      <CardContent className="space-y-2">
        <div className="flex items-center justify-between">
          <span className="text-sm text-muted-foreground">Meetings summarized</span>
          <TrendingUp className="size-4 text-success" />
        </div>
        <p className="text-3xl font-semibold tracking-tight text-foreground">128</p>
        <Badge variant="success">+12% this week</Badge>
      </CardContent>
    </CardContainer>
  );
}

function MediaCard() {
  return (
    <CardContainer className="overflow-hidden">
      <div className="relative flex aspect-video items-center justify-center bg-gradient-to-br from-slate-800 to-slate-950">
        <span className="inline-flex size-12 items-center justify-center rounded-full bg-background/95 text-foreground shadow-md">
          <Play className="size-5 translate-x-0.5 fill-current" />
        </span>
      </div>
      <CardContent className="space-y-1">
        <CardTitle>CPQ Q3 scope review</CardTitle>
        <CardDescription>45:00 · Summarized</CardDescription>
      </CardContent>
    </CardContainer>
  );
}

function ProgressCard() {
  return (
    <CardContainer>
      <CardHeader>
        <div>
          <CardTitle>Onboarding</CardTitle>
          <CardDescription>2 of 3 steps</CardDescription>
        </div>
        <Badge>66%</Badge>
      </CardHeader>
      <CardDivider />
      <CardContent className="space-y-3">
        <Progress value={66} aria-label="Onboarding progress" />
        <Button variant="link" rightIcon={<ArrowUpRight className="size-4" />}>
          Continue setup
        </Button>
      </CardContent>
    </CardContainer>
  );
}

function TeamCard() {
  return (
    <CardContainer>
      <CardHeader>
        <div>
          <CardTitle>Workspace</CardTitle>
          <CardDescription>4 members</CardDescription>
        </div>
        <CardAction>Manage</CardAction>
      </CardHeader>
      <CardDivider />
      <CardContent className="flex items-center justify-between">
        <div className="flex -space-x-2">
          {["Eric Idle", "Zoe Ray", "Ada Lin", "Sam Poe"].map((n) => (
            <Avatar key={n} name={n} className="size-8 ring-2 ring-background" />
          ))}
        </div>
        <Button variant="secondary" size="sm" leftIcon={<Users className="size-4" />}>
          Invite
        </Button>
      </CardContent>
    </CardContainer>
  );
}

export const Default: Story = {
  render: () => (
    <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-4">
      <StatCard />
      <MediaCard />
      <ProgressCard />
      <TeamCard />
    </div>
  ),
};

import type { Meta, StoryObj } from "@storybook/react";
import { LoginPage } from "./login-page";
import { LoginPageShadcn } from "./login-page-shadcn";
import { LoginMui3 } from "./login-mui3";

const meta = {
  title: "Examples/Login",
  parameters: { layout: "fullscreen" },
